CREATE DATABASE IF NOT EXISTS manstudy CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci; USE manstudy;
CREATE TABLE roles(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(50) NOT NULL,slug VARCHAR(30) NOT NULL UNIQUE);
INSERT INTO roles(name,slug) VALUES('Super Admin','super_admin'),('Tata Usaha','tu'),('Kepala Madrasah','kepala'),('Alumni','alumni');
CREATE TABLE users(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,role_id INT UNSIGNED NOT NULL,username VARCHAR(50) UNIQUE,email VARCHAR(120) UNIQUE,password VARCHAR(255) NOT NULL,force_change_password TINYINT(1) DEFAULT 0,name VARCHAR(120) NOT NULL,is_active TINYINT(1) DEFAULT 1,last_login DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE login_attempts(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,ip_address VARCHAR(45) NOT NULL,login VARCHAR(100) NOT NULL,time INT UNSIGNED DEFAULT NULL);
CREATE TABLE jurusan(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE tahun_lulus(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(10) NOT NULL UNIQUE);
CREATE TABLE status_alumni(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(50) NOT NULL UNIQUE);
INSERT INTO status_alumni(name) VALUES('Kuliah'),('Kerja'),('Wirausaha'),('Belum Bekerja');
CREATE TABLE alumni(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL UNIQUE,nisn VARCHAR(20) NOT NULL UNIQUE,nik VARCHAR(20),name VARCHAR(120) NOT NULL,gender ENUM('L','P') NULL,birth_place VARCHAR(100),birth_date DATE,address TEXT,phone VARCHAR(30),email VARCHAR(120),jurusan_id INT UNSIGNED NULL,tahun_lulus_id INT UNSIGNED NULL,status_alumni_id INT UNSIGNED NULL,photo VARCHAR(255),verification_status ENUM('pending','verified','rejected') DEFAULT 'pending',registered_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(jurusan_id) REFERENCES jurusan(id),FOREIGN KEY(tahun_lulus_id) REFERENCES tahun_lulus(id),FOREIGN KEY(status_alumni_id) REFERENCES status_alumni(id));
CREATE TABLE pertanyaan(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,question TEXT NOT NULL,type ENUM('text','textarea','radio','checkbox','select','date','number') NOT NULL,options TEXT NULL,sort_order INT DEFAULT 0,category VARCHAR(100) NULL,parent_id INT UNSIGNED NULL,parent_value VARCHAR(255) NULL,question_key VARCHAR(50) UNIQUE NULL,is_active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
INSERT INTO pertanyaan(question,type,options,sort_order,category,question_key) VALUES('Apa aktivitas utama Anda saat ini?','radio','Melanjutkan Pendidikan|Bekerja|Berwirausaha|Sedang Mencari Pekerjaan|Belum Bekerja|Lainnya',1,'Status Alumni','activity');
CREATE TABLE tracer(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,alumni_id INT UNSIGNED NOT NULL UNIQUE,status ENUM('draft','submitted') DEFAULT 'draft',submitted_at DATETIME NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(alumni_id) REFERENCES alumni(id) ON DELETE CASCADE);
CREATE TABLE jawaban(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tracer_id INT UNSIGNED NOT NULL,pertanyaan_id INT UNSIGNED NOT NULL,answer TEXT,UNIQUE KEY uq_answer(tracer_id,pertanyaan_id),FOREIGN KEY(tracer_id) REFERENCES tracer(id) ON DELETE CASCADE,FOREIGN KEY(pertanyaan_id) REFERENCES pertanyaan(id));
CREATE TABLE legalisir(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,alumni_id INT UNSIGNED NOT NULL,quantity INT NOT NULL,notes TEXT,status ENUM('pending','processing','completed','rejected') DEFAULT 'pending',result_file VARCHAR(255) NULL,processed_by INT UNSIGNED NULL,processed_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(alumni_id) REFERENCES alumni(id) ON DELETE CASCADE,FOREIGN KEY(processed_by) REFERENCES users(id));
CREATE TABLE legalisir_file(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,legalisir_id INT UNSIGNED NOT NULL,file_path VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(legalisir_id) REFERENCES legalisir(id) ON DELETE CASCADE);
CREATE TABLE log_activity(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,action VARCHAR(255) NOT NULL,module VARCHAR(80),reference_id INT UNSIGNED NULL,ip_address VARCHAR(45),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE settings(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,setting_key VARCHAR(100) UNIQUE,setting_value TEXT); CREATE TABLE notifications(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,title VARCHAR(150),body TEXT,is_read TINYINT(1) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id)); CREATE TABLE password_reset(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,token VARCHAR(255) NOT NULL,expires_at DATETIME NOT NULL,used_at DATETIME NULL,FOREIGN KEY(user_id) REFERENCES users(id));
